userscript.function:

//기본탭 제외하고 숨김처리
tabObj.forEachCell(function(e){
    const tId = e._idd
    if(!DEFAULT_TAB_LIST.includes) {
        tabObj.tabs(tId).hide();
    }
});

//결재문서함 또는링크모드 모드일때 취소버튼 제거
if(Sepoa.request.onLink || Sepoa.request.MODE == 'POPUP'){
    btnObj.showButton('CANCEL', false);
}

//서명방식 기본 값 지정
formObj.setValue('CONT_METHOD', 'D');    // D : 디지털 서명

//템플릿 번호 아이템 readonly
formObj.setReadOnly('CONT_FORM_NO', true);

//협력사일때 동작
if(Sepoa.info.USER_TYPE == 'S'){
    formObj.hideItem('SELECT_CFGL');
}

//모듈에 의한 탭 활성화
const childTabModule = sUtils.workflow.getChildren('CT1636946702720');
for(let i in childTabModule){
    const tID = sUtils.workflow.getAlias(childTabModule[i]);
    if(tID != undefined){
        if(sUtils.workflow.check(childTabModule[i])){
            tabObj.tabs(tID).show();
            tabObj.callEvent("onSelect", [tID]);
        }
    }
}


callFunction('p', 'childScreenReady', [{
    name:'FORM',
    fn:{
        doOpenDocument:doOpenDocument,
        doClear:doClear,
        setViewMode:setViewMode
    }
}])


const child = $share.childScreen[config.name] = config;
if ($share.config && $share.config.data) {
    child.fn.doOpenDocument($share.config);
}

if(viewFlag === true) {
    if(child.fn.setViewMode){
        child.fn.setViewMode(viewFlag);
    }
}


if (id == 'DOWN') {
    doDownloadContract();
} else if (id == 'VIEW') {
    callContractEditor($share.config.data.CONT_NO,$share.config.data.CONT_GL_SEQ);
} else if (id == 'SAVE') {
    doSave('INSERT');
} else if (id == 'CANCEL') {
    formObj.setValue("CATEGORY", "");
    formObj.setValue("SELECT_CFGL", "");
    callFunction(['p'], 'changeView', [{
        view: 'LIST'
    }]);
}


tabObj.tabs('BASIC').setActive();
formObj.clear();

for (var i in $share.childScreen) {
    $share.childScreen[i].fn.doClear();
}

delete $share.config;


doClear();
var cont_no = getDocumentNumber('CT');
$share.config = {
    document : {},
    data : { DOC_TYPE: "MA"
            ,DOC_NO : cont_no
            ,CONT_NO : cont_no
            ,CONT_GL_SEQ : "1"
            ,STATUS:"T"
    }
};
doServiceAjax("sepoa.svc.ct.CT_205", "CONNECTION", 'doQueryGetBuyerInfo', null, function(so) {
    if (so.status != 1) {
        Alert(so.message);
        return;
    } else {
        var sf = new SepoaFormater(so.result[0]);
        if (sf.getRowCount() > 0) {
            $share.config.data = $.extend(true, $share.config.data, sf.getArrayMap()[0]);
            callFunction(['CT_205_B'], 'doOpenDocument', [$share.config]);
        }
    }
    setViewMode(false);
    formObj.setValue('CONT_METHOD', 'C');
    formObj.setValue('SIGN_ORDER', 'S');
});


doClear();

//서명방식 기본 값 지정
formObj.setValue('CONT_METHOD', 'D');    // D : 디지털 서명

$share.config = config;

if($share.config.document.CONT_TYPE == 'ALTER') {
    console.log($share.config.document);
    //변경계약 버튼 클릭시 진입점
    var docInfo = $share.config.document;
}else{
    const docInfo = $share.config.document;
    if(docInfo.SMR_NUMBER) {                // 계약 대상현황에서 진입 시 계약 서식 선택을 제한한다.
        hideTemplateFormItem(true);
    }

    if($share.config.data === undefined) {
        $share.config.data = {};
    }

    if(docInfo.CONT_NO && docInfo.CONT_GL_SEQ) {
        const config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            async : false,
            contentType: "json"
        }

        const params = $.extend(true, {
            module: 'sepoa.svc.ct.CT_205',
            action: 'doQueryContract'
        }, docInfo);

        const res = sUtils.multipart.send(config, params);
        if(res.status == 1) {
            if(res.result.length > 0) {
                const docData = res.result[0];
                if(docData.CONT_FORM_NO) {
                    docData.SELECT_CFGL = [docData.CATEGORY ? docData.CATEGORY : 'I', docData.CONT_FORM_NO].join('^');
                }

                formObj.dataMapper(docData, 'json');

                if(docData instanceof Object) {
                    $share.config.data = $.extend(true, {}, docData);
                }
            }
        } else {
            Alert(res.message);
        }
    }
}

for (let i in $share.childScreen) {
    $share.childScreen[i].fn.doOpenDocument($share.config);
}


viewFlag = flag;
btnObj.showButton('SAVE', !flag);
btnObj.showButton('MANUAL_COMPLETE', flag);
btnObj.showButton('VIEW', flag);
btnObj.showButton('DOWN', flag);
if($share.config.data.CONT_METHOD != 'S' || Sepoa.info.USER_TYPE == 'S'){
    btnObj.showButton('MANUAL_COMPLETE', false);
}

formObj.setViewMode(flag);
for (var i in $share.childScreen) {
    if($share.childScreen[i].fn.setViewMode){
        $share.childScreen[i].fn.setViewMode(flag);
    }
}


if (name == 'CATEGORY') {
    if(value != ""){
        formObj.reloadComboBox('SELECT_CFGL', ['SL0062', Sepoa.info.HOUSE_CODE + "#" + Sepoa.info.COMPANY_CODE + "#" + value]);
    }
} else if (name == 'SELECT_CFGL') {
    const isHidden = formObj._apiConnector('isItemHidden', ['SELECT_CFGL']);
    if(isHidden === false) {
        if (value != '') {
            const code = value.split('^');
            //formObj.setValue("CONT_CATEGORY", code[0]);
            formObj.setValue("CONT_FORM_NO", code[1], true);

            if($share.childScreen['BASIC']?.fn?.hideVaultContract) {
                $share.childScreen['BASIC'].fn.hideVaultContract(true);
            }
        }else{
            formObj.setValue("CONT_FORM_NO", "", true);

            if(sUtils.string.isBlank($share.config.data?.EXTRA?.EX_SOURCE_NO)) {
                if($share.childScreen['BASIC']?.fn?.hideVaultContract) {
                    $share.childScreen['BASIC'].fn.hideVaultContract(false);
                }
            }
        }
    }
}

//const formData = formObj.getFormData(true);
const formData = {
    SELECT_CFGL : formObj.getValue('SELECT_CFGL'),
    CONT_FORM_NO : formObj.getValue('CONT_FORM_NO'),
    CATEGORY : formObj.getValue('CATEGORY'),
    CONT_METHOD : formObj.getValue('CONT_METHOD'),
    EXPIRED_ALARM : formObj.getValue('EXPIRED_ALARM')
}

if(!$share.config) {
    $share.config = {};
}

if(!$share.config.data) {
    $share.config.data = {};
}

$.extend(true, $share.config.data, formData);


if (!doValidate()) {
    return;
}

const data = $share.config.data;
data.grid = $share.config.grid;
data.SAVE_MODE = mode;
data.ALTER_TYPE = $share.config.document.CONT_TYPE;

if($share.config.document) {
    data.SMR_NUMBER = $share.config.document.SMR_NUMBER;
    data.NEXT_STEP = 'MODULE';
}

if (!data.CONT_FORM_NO && !$share.childScreen.BASIC.fn.doValidateAttach()) {
    Alert(Sepoa.cache.text.get('CT_205.MSG10')); // 계약 문서 또는 계약 서식이 입력되지 않았습니다.
    return;
}

const config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback : function(res, config, params) {
            if(res.status == 1) {
                if(res.result.length > 0) {
                    const docData = res.result[0];
                    if(docData instanceof Object) {
                        $.extend(true, $share.config.data, docData)
                    }

                    callContractEditor(docData.CONT_NO, docData.CONT_GL_SEQ);
                } else {
                    console.error('Document Create Failed.')
                }
            } else {
                Alert(res.message);
            }
        }
    },
    contentType: "json"
}

var params = $.extend(true, {
    module: 'sepoa.svc.ct.CT_205',
    action: 'doSaveContract'
}, data);
sUtils.multipart.send(config, params);


if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get('CT_205.MSG6'))
    return false;
}

for (var i in $share.childScreen) {
    if (!$share.childScreen[i].fn.doValidate()) {
        tabObj.tabs($share.childScreen[i].name).setActive();
        return false;
    }
}

return true;


var options = {
    url: window.CONTEXT_NAME + '/Contract/Module/ContractModuleLayout.sux',
    params: {
        CONT_NO: contNo,
        CONT_GL_SEQ: contGlSeq,
        PARENT:$sObject.getOAObject('p','changeView')
    },
    title: sUtils.cache.text.get('POA_CONTRACT.TITLE_EDITOR')
}
if(["T", "P"].indexOf($share.config.data.STATUS) >= 0){
    options.params.CONT_MODULE = 'EDITOR'
}else if($share.config.data.STATUS == 'R') {
    options.params.CONT_MODULE = 'APPROVAL_REJECT'
}else if($share.config.data.STATUS == 'RP') {
    options.params.CONT_MODULE = 'REVIEW';
}else if(['RA', 'RR'].includes($share.config.data.STATUS)) {
    options.params.CONT_MODULE = 'REVIEW_DONE';
}else if($share.config.data.STATUS == "G"){
    options.params.CONT_MODULE = 'SIGN'
}else if(["X", "K"].indexOf($share.config.data.STATUS) >= 0 ){
    options.params.CONT_MODULE = 'TERMINATION'
}else if(["F", "C", "A"].indexOf($share.config.data.STATUS) >= 0 ){
    options.params.CONT_MODULE = 'COMPLETE'
}else{
    options.params.CONT_MODULE = 'VIEW'
}
sUtils.popup.modal(options);


var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res, config, params){
            if(res.flag){

            }else{
                console.log(arguments);
                Alert(res.message);
            }
        }
    }
}

var params = {
    module:"contract",
    action: "doDocumentDownload",
    CONT_NO: $share.config.data.CONT_NO,
    CONT_GL_SEQ:  $share.config.data.CONT_GL_SEQ,
    CONT_TYPE: $share.config.data.CONT_TYPE
}

sUtils.multipart.download(config, params);


if(flag) {
    formObj.setValue('SELECT_CFGL', '');
    formObj.hideItem('SELECT_CFGL');
    formObj.hideItem('CONT_FORM_NO');
} else {
    formObj.showItem('SELECT_CFGL');
    formObj.showItem('CONT_FORM_NO');
}
